// Route53 / Global Traffic Manager Routing Policy Configuration
{
  "RecordName": "api.global-platform.com",
  "RoutingPolicy": "LATENCY_WITH_HEALTH_FAILOVER",
  "Endpoints": [
    {
      "Region": "us-east-1",
      "Target": "alb-us-east-1.amazonaws.com",
      "HealthCheck": "https://alb-us-east-1/healthz/deep-data-plane",
      "EvaluateTargetHealth": true
    },
    {
      "Region": "eu-central-1",
      "Target": "alb-eu-central-1.amazonaws.com",
      "HealthCheck": "https://alb-eu-central-1/healthz/deep-data-plane",
      "EvaluateTargetHealth": true
    }
  ]
}
